/** The pack entries other code addresses by name - Life mode's cast (roomScene.ts) looks up each
 *  cat's poses, and a name is the only stable handle: sprite ids are minted fresh on every device
 *  that seeds the pack. Renaming one of these in the editor detaches it from the scene, which is
 *  why the scene falls back to its own drawn shapes. */
export const PACK_SPRITE_NAMES = {
  roomScene: 'Room by the window',
  scrubBrush: 'Tank brush',
  foodPellet: 'Food pellets',
} as const;

/** The emote bubble shown above a cat (roomScene.ts drawEmote). Names match the pack entries. */
export const EMOTE_SPRITE_NAMES = {
  happy: 'Emote happy',
  angry: 'Emote angry',
  sleepy: 'Emote sleepy',
  hungry: 'Emote hungry',
} as const;
export type EmoteKind = keyof typeof EMOTE_SPRITE_NAMES;

/** The three cats that live in the room. Same drawing in three coats - see
 *  pixellab-assets/cats/, built by recolouring the one generated cat rather than generating three. */
export const CAT_VARIANTS = ['orange', 'grey', 'cream'] as const;
export type CatVariant = (typeof CAT_VARIANTS)[number];
export type CatPose =
  | 'asleep'
  | 'walking'
  | 'sitting'
  | 'pouncing'
  | 'eating'
  | 'drinking'
  | 'grooming'
  | 'running'
  | 'playing'
  | 'watching'
  | 'stretching';

/** The pack entry name for one cat in one pose. Kept as a function rather than a table so a new
 *  coat only has to be added to CAT_VARIANTS and to genpack.py's PACK. */
export function catSpriteName(variant: CatVariant, pose: CatPose): string {
  return `Cat ${variant} ${pose}`;
}
